FUNCTION handleGetHealth(request):
    // REQ-fleet-temporal-conflict-v1-011; preconditions: none.
    IF local persistence unavailable THEN RETURN 503. END IF
    RETURN 200 with status = ok.
    // Authorization and transaction: none; postcondition: persistent state unchanged.

FUNCTION handleCreateDriver(request):
    // REQ-fleet-temporal-conflict-v1-013; preconditions: JSON and persistence available.
    REQUIRE authenticated admin or RETURN 401/403. REQUIRE application/json or RETURN 415.
    VALIDATE REQ-fleet-temporal-conflict-v1-002 or RETURN 422/400. BEGIN TRANSACTION.
    IF employee_code exists THEN ROLLBACK; RETURN 409. END IF CREATE driver; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback leaves persistent state unchanged.
